# Weather services: AC 00-45H Aviation Weather Services (as folded into FAA-H-8083-28A), AIM chapter 7-1. ACS area I.C. Reports are written out in text, no chart figures.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "METAR", "A METAR reads: KMWX 141853Z 27012G20KT 5SM -RA BR BKN012 OVC025 14/12 A2992. What is the ceiling?",
      ["1,200 feet AGL", "2,500 feet AGL", "1,200 feet MSL"],
      "The ceiling is the lowest broken or overcast layer (or vertical visibility). BKN012 is broken at 1,200 feet above ground level; METAR cloud heights are AGL."),
    S(1, 2, "METAR", "In the same METAR, 27012G20KT means the wind is from",
      ["270 degrees true at 12 knots, gusting to 20 knots",
       "270 degrees magnetic at 12 knots, gusting to 20 knots",
       "270 degrees true at 20 knots, gusting to 12 knots"],
      "METAR and TAF wind directions are referenced to true north and speeds are in knots; G marks the peak gust. Winds broadcast by ATIS and towers are magnetic."),
    S(1, 2, "TAF", "In a TAF, what does the group TEMPO 2014/2017 2SM TSRA BKN030CB mean?",
      ["Temporary thunderstorms with 2 miles visibility, each lasting under an hour, between 1400Z and 1700Z on the 20th",
       "A steady change to thunderstorms and 2 miles visibility beginning at 1400Z and lasting until 1700Z the next day",
       "A 20 percent chance of thunderstorms with 2 miles visibility from 2014Z until 2017Z on the same date"],
      "TEMPO forecasts temporary fluctuations that last less than an hour each and cover less than half the period. 2014/2017 is the 20th day from 1400Z to 1700Z UTC. A lasting change uses FM or BECMG; probabilities use PROB30 or PROB40."),
    S(1, 1, "AIRMETs", "Which AIRMET covers moderate icing and the freezing level?",
      ["AIRMET Zulu", "AIRMET Tango", "AIRMET Sierra"],
      "AIRMET Sierra covers IFR conditions and mountain obscuration, Tango covers moderate turbulence, sustained surface winds of 30 knots or more and low-level wind shear, and Zulu covers moderate icing and freezing levels."),
    S(1, 2, "SIGMETs", "A SIGMET (not a convective SIGMET) is issued for which hazard?",
      ["Severe icing not associated with thunderstorms",
       "Moderate turbulence affecting a wide area of the country",
       "Ceilings below 1,000 feet over a wide area"],
      "SIGMETs cover severe icing, severe or extreme turbulence, dust or sandstorms lowering visibility below 3 miles, and volcanic ash, all not associated with thunderstorms. Moderate turbulence and widespread IFR are AIRMET items."),
    S(1, 3, "Winds aloft", "A winds and temperatures aloft forecast shows 2415+05 for 6,000 feet. What does it mean?",
      ["Wind from 240 degrees true at 15 knots, temperature plus 5 degrees C",
       "Wind from 240 degrees magnetic at 15 knots, temperature plus 5 degrees F",
       "Wind from 150 degrees true at 24 knots, temperature plus 5 degrees C"],
      "The first two digits are direction in tens of degrees true, the next two the speed in knots, and the last group the temperature in degrees Celsius."),
    S(1, 1, "Briefings", "Which type of preflight briefing should you request when your departure is more than 6 hours away?",
      ["An outlook briefing", "A standard briefing", "An abbreviated briefing"],
      "The AIM recommends an outlook briefing when departure is 6 or more hours away, a standard briefing when you have no prior weather information, and an abbreviated briefing to update or add to earlier information."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "METAR", "A METAR includes VV004. What does it mean?",
      ["An indefinite ceiling with a vertical visibility of 400 feet",
       "Variable visibility of 4 statute miles near the station",
       "A broken layer at 400 feet with the tops not reported"],
      "VV reports vertical visibility into an obscuration such as fog that hides the whole sky. VV004 is an indefinite ceiling at 400 feet AGL."),
    S(2, 2, "TAF", "A TAF group reads FM1600 31010KT P6SM SCT040. What visibility is forecast from 1600Z?",
      ["Greater than 6 statute miles", "Exactly 6 statute miles", "Prevailing visibility of 6 kilometers"],
      "P6SM means plus 6 statute miles, more than 6 statute miles. FM marks a rapid and lasting change starting at the time given, here 1600Z."),
    S(2, 1, "PIREPs", "A pilot report that begins with the code UUA is",
      ["an urgent pilot report", "a routine pilot report", "an unverified pilot report"],
      "UA is a routine PIREP and UUA an urgent PIREP, used for hazards such as tornadoes, severe icing or turbulence, low-level wind shear, hail or volcanic ash."),
    S(2, 2, "Convective SIGMETs", "Which condition leads to a convective SIGMET?",
      ["An area of embedded thunderstorms",
       "Moderate icing in clouds over a wide area",
       "Surface winds sustained at 30 knots or more"],
      "Convective SIGMETs cover severe thunderstorms, lines of thunderstorms, embedded thunderstorms, areas of heavy precipitation from storms, tornadoes and hail of 3/4 inch or more. Moderate icing and strong surface winds are AIRMET items."),
    S(2, 3, "Winds aloft", "A winds aloft forecast for 30,000 feet shows 731552. What is the forecast?",
      ["Wind from 230 degrees true at 115 knots, temperature minus 52 degrees C",
       "Wind from 230 degrees true at 15 knots, temperature plus 52 degrees C",
       "Wind from 310 degrees true at 75 knots, temperature minus 52 degrees C"],
      "For winds of 100 knots or more, 50 is added to the direction and 100 subtracted from the speed. 73 minus 50 gives 230 degrees and 15 plus 100 gives 115 knots. Above 24,000 feet temperatures are always below zero, so the minus sign is omitted."),
    S(2, 2, "Winds aloft", "Why does a winds and temperatures aloft forecast show no wind for the 3,000-foot level at a mountain station?",
      ["Winds are not forecast within 1,500 feet of the station elevation",
       "The station only forecasts winds that are above 12,000 feet MSL",
       "Winds at that level are always light and variable at mountains"],
      "No winds are forecast for levels within 1,500 feet of the station elevation, and no temperatures for the 3,000-foot level or within 2,500 feet of the station elevation."),
    S(2, 3, "Graphical forecasts", "Which product has replaced the old textual area forecast for the contiguous United States?",
      ["The Graphical Forecasts for Aviation (GFA)",
       "The Terminal Aerodrome Forecast (TAF) for each airport",
       "The Center Weather Advisory (CWA)"],
      "The Aviation Weather Center's GFA tool replaced the textual area forecast (FA) for the lower 48 states. TAFs cover only about 5 statute miles around an airport, and CWAs are short-term unscheduled advisories."),
    # ---------- Drill only ----------
    S(0, 1, "METAR", "What is the time reference in a METAR such as 141853Z?",
      ["Coordinated Universal Time (UTC)", "Local standard time at the reporting station", "Local daylight time"],
      "141853Z is the 14th day of the month at 1853 UTC (Zulu). All times in METARs and TAFs are UTC."),
    S(0, 2, "METAR", "In a METAR, the group 14/12 A2992 shows",
      ["temperature 14 degrees C, dewpoint 12 degrees C, altimeter 29.92",
       "dewpoint 14 degrees C, temperature 12 degrees C, altimeter 29.92",
       "temperature 14 degrees F, dewpoint 12 degrees F, altimeter 29.92"],
      "Temperature comes first and dewpoint second, both in degrees Celsius. A2992 is the altimeter setting, 29.92 inches of mercury. A small spread like this suggests fog or low clouds may form."),
    S(0, 2, "METAR", "What does -RA BR mean in a METAR's weather group?",
      ["Light rain and mist", "Heavy rain and haze", "Light rain and blowing snow"],
      "The minus sign means light intensity, RA is rain and BR is mist. HZ is haze and BLSN is blowing snow."),
    S(0, 1, "TAF", "A standard TAF covers an area within about how far of the center of the runway complex?",
      ["5 statute miles", "10 statute miles", "25 statute miles"],
      "A TAF describes forecast conditions within 5 statute miles of the center of the airport's runway complex. VC (vicinity) refers to 5 to 10 statute miles."),
    S(0, 2, "TAF", "In a TAF, what does PROB30 1920/1923 mean?",
      ["A 30 percent probability of the listed weather between 2000Z and 2300Z on the 19th",
       "The listed weather is 30 percent likely to last from 1920Z until 1923Z the same day",
       "A 30 percent chance that the whole forecast changes after 1900Z on the 20th day"],
      "PROB30 gives a 30 percent probability of the following conditions, and 1920/1923 is the 19th day from 2000Z to 2300Z UTC."),
    S(0, 2, "AIRMETs", "Sustained surface winds of 30 knots or more over a large area are covered by which advisory?",
      ["AIRMET Tango", "AIRMET Sierra", "A convective SIGMET"],
      "AIRMET Tango covers moderate turbulence, sustained surface winds of 30 knots or more and nonconvective low-level wind shear."),
    S(0, 2, "Center Weather Advisory", "What is a Center Weather Advisory?",
      ["An unscheduled warning for conditions meeting or nearing advisory criteria, for the next 2 hours",
       "A scheduled forecast issued four times a day for the whole of an ARTCC's airspace and its airports",
       "A routine report of actual weather at the airports inside one ARTCC's area"],
      "A CWA is an unscheduled advisory issued by an ARTCC's weather unit for conditions that meet or approach AIRMET, SIGMET or convective SIGMET criteria, valid for up to 2 hours."),
    S(0, 3, "Surface analysis", "On a surface analysis chart, isobars that are close together indicate",
      ["a strong pressure gradient and strong winds",
       "a weak pressure gradient and light winds",
       "an area of high humidity and possible fog or low stratus"],
      "Isobars connect points of equal pressure. Close spacing means pressure changes quickly over a short distance, which drives stronger winds."),
    S(0, 2, "PIREPs", "Why are pilot reports especially valuable to forecasters and other pilots?",
      ["They are the only direct reports of cloud tops, icing and turbulence aloft",
       "They are required before every flight under the Federal Aviation Regulations",
       "They replace the METAR at airports where there is no weather observer"],
      "Most observations are made at the surface. PIREPs give real conditions aloft, such as cloud tops, icing and turbulence, that no other source measures directly."),
    S(0, 3, "Convective outlook", "What does a convective outlook describe?",
      ["The potential for severe and general thunderstorms over the coming days",
       "The present location of thunderstorms detected by weather radar",
       "Turbulence and icing forecast in the lower layers of the atmosphere for the next 12 hours"],
      "The Storm Prediction Center's convective outlook forecasts where general and severe thunderstorms may develop over the next days, useful for planning. Radar shows storms that exist now."),
]
